// Hand-written. Not generated by Speakeasy.
//
// Guards the attributes marked stable across updates.
//
// Without this, every update plans them as "known after apply". That is not
// cosmetic: client_secret going unknown makes every consumer of it -- a Vault
// entry, a Kubernetes secret, a replace_triggered_by -- plan a write whenever
// any unrelated field changes. It also drags dependent resources into a plan
// that should not touch them, because a client referencing
// authlete_service.x.api_key sees that reference go unknown.
//
// The wiring is x-speakeasy-plan-modifiers in the overlay, so an overlay edit
// could drop it and nothing else would notice: the provider still builds, and
// every test that does not inspect a plan still passes.
package provider

import (
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
)

// stableAcrossUpdates cannot change as a side effect of an update: identifiers,
// the creation timestamp, and secrets, which change only through explicit
// rotation. modified_at is deliberately absent -- it changes on every update by
// definition, and marking it stable would hide that.
var stableAcrossUpdates = map[string][]string{
	"authlete_service": {"api_key", "api_secret", "created_at", "number", "service_owner_number"},
	"authlete_client":  {"client_id", "client_secret", "created_at", "number", "service_number"},
}

func TestStableAttributesKeepTheirValueInPlans(t *testing.T) {
	for name, res := range map[string]resource.Resource{
		"authlete_service": NewServiceResource(),
		"authlete_client":  NewClientResource(),
	} {
		attrs := resourceSchema(t, res).Attributes
		for _, attrName := range stableAcrossUpdates[name] {
			attr, ok := attrs[attrName]
			if !ok {
				t.Errorf("%s has no %q attribute; update this test or the overlay", name, attrName)
				continue
			}
			if countPlanModifiers(attr) == 0 {
				t.Errorf("%s.%s has no plan modifier, so every update plans it as unknown.\n\n"+
					"For client_secret and api_key that makes dependent resources plan writes "+
					"on every unrelated change.\n\n"+
					"Restore the x-speakeasy-plan-modifiers entry for this property in "+
					".speakeasy/terraform_overlay.yaml.", name, attrName)
			}
		}
	}
}

// modified_at must NOT be marked stable: it changes on every update, and
// claiming otherwise would plan a stale value and hide a real change.
func TestModifiedAtIsNotMarkedStable(t *testing.T) {
	for name, res := range map[string]resource.Resource{
		"authlete_service": NewServiceResource(),
		"authlete_client":  NewClientResource(),
	} {
		attrs := resourceSchema(t, res).Attributes
		if attr, ok := attrs["modified_at"]; ok && countPlanModifiers(attr) > 0 {
			t.Errorf("%s.modified_at carries a plan modifier.\n\n"+
				"It changes on every update, so planning it from state would show a stale "+
				"timestamp and suppress a real change.", name)
		}
	}
}

func countPlanModifiers(attr schema.Attribute) int {
	switch a := attr.(type) {
	case schema.StringAttribute:
		return len(a.PlanModifiers)
	case schema.Int64Attribute:
		return len(a.PlanModifiers)
	case schema.Int32Attribute:
		return len(a.PlanModifiers)
	case schema.BoolAttribute:
		return len(a.PlanModifiers)
	}
	return 0
}
